@pytest.mark.parametrize("case", N1_CASES) @pytest.mark.parametrize("dtype", ["float32", *N1_DTYPES]) def test_n1_batchnorm_running_stats(dtype, case): layer, _, _ = E3._e3_layer("BatchNorm1D", dtype) assert layer.momentum == N1_BN_MOMENTUM rm0, rv0 = E3._np(layer.running_mean), E3._np(layer.running_var) x = E3._const(E3.e3_inputs("BatchNorm1D", case), dtype) layer(x) rm, rv = layer.running_mean, layer.running_var C = E3.E3_SHAPE["BatchNorm1D"][1] assert rm.dtype == rv.dtype == "float32" and tuple(rm.shape) == tuple(rv.shape) == (C,) x64 = E3._np(x) N, m, u = x64.shape[0], N1_BN_MOMENTUM, 2.0 ** -24 mu, var = x64.mean(axis=0), x64.var(axis=0) want_m, want_v = (1 - m) * rm0 + m * mu, (1 - m) * rv0 + m * var reference = np.concatenate([want_m, want_v]) assert np.all(np.isfinite(reference)) and np.all(reference != 0) and np.ptp(reference) > 0 # L19 d_mean = (N + 1) * u * np.abs(x64).mean(axis=0) tol_m = m * d_mean + 3 * u * np.abs(want_m) + 2.0 ** -149 tol_v = m * ((N + 3) * u * var + d_mean ** 2) + 3 * u * np.abs(want_v) + 2.0 ** -149 err_m, err_v = np.abs(E3._np(rm) - want_m), np.abs(E3._np(rv) - want_v) > assert np.all(err_m <= tol_m), (err_m.max(), tol_m.min()) E AssertionError: (np.float64(4.4250860810279846e-05), np.float64(9.230025170836599e-08)) E assert np.False_ E + where np.False_ = <function all at 0x728e9df304f0>(array([4.27249819e-05, 4.42508608e-05, 1.22066587e-05, 1.83109194e-05]) <= array([9.78929165e-08, 9.23002517e-08, 9.63380444e-08, 1.00618490e-07])) E + where <function all at 0x728e9df304f0> = np.all
